suite("a password the policy refuses", () => {
  const refused = (code: string, limit?: number) =>
    new ApiError(422, { code: "invalid_fields", title: "Some fields are not valid.", errors: [{ field: "password", code, limit }] })
  it("says the minimum, the problem's own or the realm's", () => {
    expect(passwordRefusal(refused("too_short", 14))).toBe(t("passwordTooShort", { min: 14 }))
    expect(passwordRefusal(refused("too_short", 14))).toContain("14")
    expect(passwordRefusal(refused("too_short"))).toBe(t("passwordTooShort", { min: passwordPolicy.min }))
  })
  it("says the maximum", () => {
    expect(passwordRefusal(refused("too_long", 128))).toBe(t("passwordTooLong", { max: 128 }))
  })
  it("says a common or a breached one is", () => {
    expect(passwordRefusal(refused("common"))).toBe(t("passwordCommon"))
    expect(passwordRefusal(refused("breached"))).toBe(t("passwordBreached"))
  })
  it("is what a notice says, not to review the fields", () => {
    expect(describe(refused("too_short", 12))).toBe(t("passwordTooShort", { min: 12 }))
    expect(describe(refused("breached"))).not.toBe(t("fixFields"))
  })
  it("says nothing of another field", () => {
    const other = new ApiError(422, { code: "invalid_fields", title: "Some fields are not valid.", errors: [{ field: "name", code: "required" }] })
    expect(passwordRefusal(other)).toBe("")
    expect(describe(other)).toBe(t("fixFields"))
  })
})

